// Bloom's-aligned MCQs. Each topic follows the progression:
// Q1-Q2 Remember · Q3-Q4 Understand · Q5-Q7 Apply · Q8 Analyze · Q9 Evaluate · Q10 Create
// All distractors are equal or longer than the correct option — students
// can no longer scan-and-pick the longest. Every option makes a complete,
// plausible claim of similar visual weight.

import type { Question } from "./module1-mcq";

export const mcqData: Record<number, Question[]> = {
  // ─── Topic 1: What Is Social Media / How It Changed Communication ───
  1: [
    { q: "Which statement most accurately defines social media?", opts: ["Platforms where users create, share, and interact with each other in both directions", "Any website that shows news articles, blog posts, or official company press releases", "Messaging apps like WhatsApp and Telegram used for one-to-one private conversations", "TV channels and radio stations that have moved their broadcasts online to a website"], ans: 0, why: "The defining features are user-generated content and two-way interaction — users create, share, and interact with content AND with each other. News sites are consumer-only, messaging apps are one-to-one, and online TV is still broadcast.", bloom: "remember" },
    { q: "Before social media, how did most communication from brands and media reach ordinary people?", opts: ["Through letters posted by mail that the audience could reply to within a few days", "Through one-way broadcast — TV, radio, and newspapers with almost no audience reply", "Through phone calls made personally from the company director to every customer", "Through town-hall meetings held every week in every neighbourhood across the country"], ans: 1, why: "Traditional media was one-way broadcast. Audiences watched or read but could not reply in real time. Social media flipped this into a two-way conversation where anyone can respond publicly.", bloom: "remember" },
    { q: "Why is the shift from one-way broadcast to two-way interaction considered the most important change social media introduced?", opts: ["Because advertising became illegal once platforms like Facebook and Instagram launched worldwide", "Because communication became slower and more thoughtful compared to traditional newspaper articles", "Because audiences gained the ability to reply, share, and create content that competes with brands", "Because face-to-face meetings in cafes and classrooms were entirely replaced by online chatting"], ans: 2, why: "Audiences became creators. Feedback turned instant, and brands could no longer speak AT people without a reply — they had to start listening and responding like a peer in the conversation.", bloom: "understand" },
    { q: "A student says \"social media is just for fun, not for business.\" What's the clearest reason this view is incomplete?", opts: ["Businesses are banned from having accounts on most social media platforms unless they pay a yearly fee and most modern teams have moved to exactly this way of doing things", "Most customers now discover new cafes, clothes, and services through their Instagram and TikTok feeds daily", "Fun and business are the same thing, so the statement is correct and needs no further improvement", "Business only happens inside physical shops where customers can touch the product before they buy it"], ans: 1, why: "Discovery has moved online. Students scrolling TikTok or Instagram find new cafes, brands, and services every day, which is exactly where small businesses now need to be visible.", bloom: "understand" },
    { q: "A small Tashkent café posts a photo of their new dessert and it gets shared 10,000 times organically. Which social-media property is most responsible?", opts: ["The café paid Instagram a large sum of money to boost the post to a worldwide paid audience", "Google News indexed the photo and pushed it to the top of search results across the whole country", "The network effect — each share exposes the post to new audiences, multiplying reach for free", "A local Tashkent TV channel picked up the story and broadcast it during the evening news hour"], ans: 2, why: "Organic virality happens because each share exposes the post to a new audience for free. The café's reach isn't rented (ads) or broadcast (TV) — it's multiplied by user action, which is the network effect.", bloom: "apply" },
    { q: "A local bakery with 500 loyal customers asks: \"Is social media useful for us or is it a distraction?\" What's the best answer?", opts: ["Useless because they already have enough customers and social media only works for international brands", "Useful for staying top-of-mind, getting referrals, collecting feedback, and showing product quality", "Only useful after they grow past 10,000 followers — below that number it is a complete waste of time", "Only useful for online-only businesses that have no physical shop or regular walk-in foot traffic"], ans: 1, why: "Social media keeps the bakery top-of-mind with existing customers (their posts appear in the feed), brings referrals, collects quick feedback, and shows quality through process photos. Benefits scale with consistency, not follower count.", bloom: "apply" },
    { q: "A Tashkent student creator wants to grow from 200 to 5,000 followers in six months. Which approach best uses how social media actually works?", opts: ["Buy 5,000 followers from a cheap website and then stop posting because the number is already reached", "Post once a month with a very long caption and hope the algorithm pushes it to many people eventually", "Post consistent, relatable content a few times a week, reply to comments, and collaborate with peers", "Send private messages to 5,000 strangers every single day begging each of them to follow the account"], ans: 2, why: "Real growth follows consistency + engagement + collaboration. Bought followers don't interact, so the algorithm stops showing your posts. Posting regularly and replying builds an active audience the algorithm rewards.", bloom: "apply" },
    { q: "Analyse why a respected news outlet might LOSE credibility when it moves from TV to social media platforms.", opts: ["There is no reason — credibility is a fixed number that never changes regardless of the platform used", "News outlets are technically not allowed to post on social platforms under international journalism rules and most modern teams have moved to exactly this way of doing things", "Social media makes every article automatically more credible because more people see it on their feed", "On social media, news mixes with opinion, ads, and misinformation in one feed, and comments travel with it"], ans: 3, why: "Algorithmic ranking favours engagement over accuracy, news sits next to opinion and ads, and comment sections let criticism (fair or not) follow every article. Traditional one-way TV shielded outlets from this noise.", bloom: "analyze" },
    { q: "A café owner considers spending 20 hours a week on social media vs hiring a part-time barista. Evaluate the decision.", opts: ["Social media always wins because online presence is more important than the actual café experience", "A barista always wins because physical service is the only thing that matters for any small food business", "It depends on the current bottleneck — if awareness is low, social wins; if service is slow, barista wins", "Neither option is worth pursuing because small cafes cannot realistically improve through either of them"], ans: 2, why: "It depends on the real bottleneck. If people don't know the café, social media has higher ROI. If customers wait too long and leave, a barista helps more. Evaluating a trade-off means asking what each option actually fixes.", bloom: "evaluate" },
    { q: "Design a 30-day social media launch plan for a new student café on campus. Which platforms, what content, and what cadence?", opts: ["Post randomly whenever the owner feels inspired without any plan or schedule across every social platform", "Instagram + TikTok, themed weekly content, 4 posts per week plus daily Stories showing behind-the-scenes", "Post 50 times a day on every platform available to maximise the chance of going viral with at least one", "LinkedIn only, sharing long formal press releases about the café's mission and leadership team each week"], ans: 1, why: "Instagram (food photos, Reels) + TikTok (behind-the-scenes, barista quick tips) match the student audience. Week 1 announce, Week 2 testimonials, Week 3 club collabs, Week 4 user-generated reposts. 4 posts/week + daily Stories is realistic and trackable.", bloom: "create" },
  ],

  // ─── Topic 2: Major Platforms ───
  2: [
    { q: "Which platform is primarily known for professional networking and business-to-business content?", opts: ["TikTok, which is mostly used by younger audiences for short vertical video entertainment", "Snapchat, which is mostly used by friends to share disappearing photos and silly filters", "LinkedIn, which is built around jobs, industry articles, and professional conversations", "Pinterest, which is mostly used for visual inspiration, home decor, and recipe saving"], ans: 2, why: "LinkedIn is the professional network — jobs, industry articles, B2B marketing. The others skew entertainment, personal, or visual inspiration.", bloom: "remember" },
    { q: "Which platform is famous for short vertical videos with a strong algorithmic \"For You\" feed?", opts: ["TikTok, where the algorithm pushes short videos to people who don't even follow the creator", "LinkedIn, where the main feed is text posts written by working professionals sharing career insights", "Pinterest, where users mostly save inspirational images onto personal boards arranged by topic", "Facebook, where the main feed shows long text updates from family members and childhood friends"], ans: 0, why: "TikTok's For You page uses the algorithm to show videos based on interest, not who you follow — that's why creators with zero followers can still go viral.", bloom: "remember" },
    { q: "Why does the same brand often post different content on LinkedIn vs TikTok, even about the same product?", opts: ["Because the company has a lazy marketing team that cannot be bothered to coordinate a single message", "Because each platform has its own culture, audience, and format — same message needs different packaging", "Because platforms technically ban brands from posting the exact same content on more than one service and most modern teams have moved to exactly this way of doing things", "Because the company doesn't plan ahead and just randomly guesses what will work on each separate app"], ans: 1, why: "Each platform has its own culture and format. LinkedIn expects text/articles for professionals; TikTok expects short vertical video for entertainment. Copy-paste kills performance.", bloom: "understand" },
    { q: "Why is it risky for a small business to try to be active on every single social media platform at once?", opts: ["Because platforms will automatically delete your account if you sign up for more than three of them at once", "Because time and energy get diluted across platforms, so each one gets low-quality posts and poor results", "Because users are not technically allowed to view a small business account on more than one platform", "Because the algorithms of different platforms secretly punish any brand that is present on competitor apps"], ans: 1, why: "Time dilution is the core risk. Small teams can't maintain 5 platforms at quality — depth compounds, spread dilutes. Pick where your audience lives and go deep.", bloom: "understand" },
    { q: "A B2B software company selling to IT managers wants to build thought leadership. Which primary platform fits best?", opts: ["TikTok because it has the biggest reach among teenagers who share videos with their school friends", "Facebook because it has the largest general-purpose audience of all ages across many different countries", "LinkedIn because IT managers and CTOs are professionally active there and long posts actually get read", "Pinterest because visual inspiration boards work well for software products sold to enterprise customers"], ans: 2, why: "The decision-makers (IT managers, CTOs) are professionally active on LinkedIn. Reach alone doesn't matter; reaching the RIGHT audience does.", bloom: "apply" },
    { q: "A 19-year-old fashion brand in Tashkent wants to reach female Gen Z buyers. Rank Instagram, TikTok, and LinkedIn for this goal.", opts: ["LinkedIn first because working professionals have more money to spend on expensive fashion purchases", "LinkedIn only because serious brands should never use platforms known mainly for entertainment videos", "All three are equal because every platform has every possible type of user in roughly the same quantity", "TikTok and Instagram are both strong for this audience; LinkedIn is the weakest because of audience fit"], ans: 3, why: "TikTok for short-form viral, Instagram for aesthetic + Reels + shopping tags. LinkedIn's audience skews older and professional, so it's bottom for Gen Z fashion.", bloom: "apply" },
    { q: "An Uzbek snack brand wants local everyday engagement with families aged 25-45. Which platforms fit best for this goal?", opts: ["Facebook plus Telegram because families use them daily for local news, groups, and neighbourhood chats", "Only Snapchat because it is technically the most popular platform in the whole Central Asian region", "LinkedIn and only LinkedIn because serious local brands should always talk to adults on professional apps", "Pinterest and only Pinterest because it is the biggest platform in the world for food-based content"], ans: 0, why: "In Uzbekistan, Facebook and Telegram have strong adoption with families — Telegram especially for local news channels and community groups. Matching platform to the real audience's daily habits is the skill.", bloom: "apply" },
    { q: "A brand posts the same photo on Instagram, Twitter/X, and LinkedIn. Instagram does well; Twitter does okay; LinkedIn underperforms. Why?", opts: ["LinkedIn's system is broken and is simply not showing the post to any of the brand's actual followers", "The photo was too small in resolution, so LinkedIn's algorithm hid it while the other platforms kept it and most modern teams have moved to exactly this way of doing things", "Photo-only content fits Instagram's visual culture but mismatches LinkedIn's text-heavy professional norms", "LinkedIn only shows video content and has banned photos from its main feed across the whole platform"], ans: 2, why: "Same pixels, different cultural fit. Photo-only works on IG's visual feed, is fine on Twitter with a caption, but LinkedIn audiences expect text-heavy insights. Match format to platform norms.", bloom: "analyze" },
    { q: "A small business owner debates: \"Be active on ALL platforms\" vs \"Pick 2 and go deep.\" Evaluate these strategies.", opts: ["Always do all platforms regardless of team size because bigger presence always produces better results", "Avoid social media entirely because it is a waste of time for any business smaller than a large company", "All platforms are always strictly better than fewer because more posts automatically means more customers", "\"Pick 2 and go deep\" almost always wins for small teams because time dilution ruins quality everywhere"], ans: 3, why: "All-platforms means low-quality posts everywhere (time-diluted) vs. high-quality presence where the audience lives. Depth compounds; spread dilutes. Expand only once two channels run smoothly.", bloom: "evaluate" },
    { q: "Design a platform mix for a Tashkent photographer who shoots local weddings AND sells presets to a global audience.", opts: ["LinkedIn only because it is the most professional platform and photography counts as a professional service", "Instagram + TikTok + Telegram — each serves a different need (showcase, reach, local client coordination)", "All fifteen major platforms at once so the photographer never misses any possible client from anywhere", "Only Telegram because it is the most popular messaging app currently used by people in Central Asia now"], ans: 1, why: "Instagram (local weddings + global preset showcase), TikTok (editing tips → preset funnel), Telegram (Tashkent community + client coordination). Two audiences served by a manageable platform set without overspreading.", bloom: "create" },
  ],

  // ─── Topic 3: Social Media Management Tools ───
  3: [
    { q: "What does Later primarily do?", opts: ["Generate long blog posts from a short prompt using artificial intelligence and publish them automatically", "Build complete Instagram chatbots that reply to customer messages with branching logic and product links", "Schedule social media posts and visually plan a content calendar across several platforms in advance", "Design professional logos, brand kits, and print-ready marketing flyers with drag-and-drop templates"], ans: 2, why: "Later is a scheduler with visual planning. ChatGPT writes, ManyChat builds bots, Canva designs — each tool has its own lane.", bloom: "remember" },
    { q: "What is Canva most commonly used for in a small social media workflow?", opts: ["Scheduling Instagram and TikTok posts automatically at the best time of day for each individual platform and most modern teams have moved to exactly this way of doing things", "Building automated chatbots that reply to DMs on Instagram with pre-written answers and product links", "Generating full blog articles from a short prompt using an artificial intelligence language model inside", "Designing graphics like posts, thumbnails, and Stories using drag-and-drop templates without design skills"], ans: 3, why: "Canva is a drag-and-drop design tool with templates for posts, thumbnails, Stories, flyers — built so non-designers can produce branded visuals fast.", bloom: "remember" },
    { q: "Why can one person running a business now look like a team of five on social media?", opts: ["Modern tools automate distinct roles — one person orchestrates design, writing, scheduling, replies, and reports", "Teams have become cheaper to hire globally, so most solo businesses secretly employ three people behind the scenes", "Business expectations for quality have dropped so dramatically that even bad content now looks professional", "Social media platforms simply no longer exist in the form they did five years ago, so less work is needed"], ans: 0, why: "Each tool replaces former headcount — Canva (design), ChatGPT (writing), Later (scheduling), ManyChat (replies), analytics dashboards (reporting). Solo leverage comes from orchestrating the stack.", bloom: "understand" },
    { q: "Why is it usually a bad idea to let ChatGPT write every caption with zero human editing?", opts: ["Because ChatGPT is technically illegal to use for any type of commercial marketing activity in most countries", "Because default outputs converge on a generic voice, so the brand starts to feel bland and interchangeable", "Because every caption it generates becomes automatically identical to those of every other brand in the world", "Because ChatGPT always writes in a single foreign language that the audience cannot read or understand at all"], ans: 1, why: "AI defaults produce generic, same-sounding text. Without a human voice editing in real stories and brand-specific phrasing, posts lose personality and engagement drops.", bloom: "understand" },
    { q: "You've finalised 20 posts for the month and want them to go out automatically at optimal times. Which tool type fits?", opts: ["A scheduler like Later, Buffer, or Metricool — pre-writing plus timed posting is exactly what they do", "A design app like Canva because it creates the visuals but cannot actually send them out to the platforms", "A writing app like ChatGPT because it drafts text but cannot publish it to Instagram or any other platform", "A spreadsheet app like Google Sheets or Excel because posts can be listed there with dates and times ready"], ans: 0, why: "Scheduler = pre-written content + automatic posting at chosen times. Canva creates, ChatGPT writes, Sheets lists — none actually publish.", bloom: "apply" },
    { q: "You need to respond to the same three FAQs sent as Instagram DMs every day. Which tool fits?", opts: ["ManyChat or another chatbot builder — it auto-replies when a DM matches a trigger phrase you configured", "Later because it handles scheduled content going out but not live incoming messages from actual customers", "Canva because it lets you design beautiful reply graphics but does not actually send them to anyone either", "Excel because you can list the FAQs in a spreadsheet and copy-paste each answer manually every single time"], ans: 0, why: "ManyChat auto-replies to repetitive questions. Repetitive replies = bot, not a human. Later schedules, Canva designs, Excel just lists — none respond in real time to DMs.", bloom: "apply" },
    { q: "A Tashkent student runs a small thrift clothing shop on Instagram alone. Pick the smallest tool stack that covers all the basics.", opts: ["Fifteen different paid tools costing over $500/month to cover every possible edge case across all platforms and most modern teams have moved to exactly this way of doing things", "Zero tools at all — everything done manually, including each post written, designed, and published by hand", "Canva free tier + ChatGPT + a free scheduler + Instagram Insights — covers design, writing, posting, and measurement", "Only Canva with nothing else, so every caption is typed live and every post is published manually each day"], ans: 2, why: "Four cheap/free tools cover the four pillars: design, writing, scheduling, measurement. This is the minimum viable stack for a solo operator and fits a student budget.", bloom: "apply" },
    { q: "A team uses ChatGPT for all captions, Canva for all graphics, Later for scheduling, ManyChat for DMs. Posts start feeling \"same-y\" and engagement drops. What's the likely cause?", opts: ["The tools are broken and the team should switch to completely different tools from a new company immediately", "Instagram secretly hates automation and suppresses any account that uses more than one tool at the same time", "Over-automation erased the brand voice — default outputs converge on a generic feel and lose distinctiveness", "ChatGPT can only write good captions once per account and then stops working correctly for all future posts"], ans: 2, why: "When everything comes from default prompts and templates, content converges on a generic feel. Fix: inject real stories, vary templates, let a human edit. The tools aren't the villain; relying on defaults is.", bloom: "analyze" },
    { q: "A founder argues: \"I'll do everything manually — tools waste time to learn.\" Evaluate this view after six months.", opts: ["Correct — tools are pure hype and every founder who uses them regrets it within about six months of starting", "Tools take many years to learn properly, so it is genuinely faster to do every single task manually forever", "Correct — doing absolutely everything manually is always the most efficient way to run any small business online", "Flawed — the learning cost of 2-3 core tools is repaid within weeks, and manual work has unbounded ongoing cost"], ans: 3, why: "Upfront learning of 2-3 tools is recouped in weeks. Manual scheduling alone eats 5+ hrs/week. Tools have a real learning curve, but manual work's ongoing cost compounds forever.", bloom: "evaluate" },
    { q: "Design a minimal tool stack for a solo entrepreneur launching on Instagram + LinkedIn. Name tools, costs, and what each replaces.", opts: ["No tools at all — do every single design, caption, post, reply, and report by hand each working day forever", "Canva + ChatGPT + Buffer/Later + native analytics — roughly $0-20/month covering design, writing, posting, measuring", "Ten paid tools costing over $500 per month even before the business has made its first sale to a real customer", "Only one single tool doing everything poorly, like trying to design inside a scheduler that has no design features and most modern teams have moved to exactly this way of doing things"], ans: 1, why: "Canva (free) for graphics, ChatGPT (free/$20) for caption drafts, Buffer/Later (free tier) for scheduling, native Insights (free) for measurement. Replaces designer, copywriter, scheduler, and analyst for $0-20/month.", bloom: "create" },
  ],

  // ─── Topic 4: Metrics and Analytics ───
  4: [
    { q: "What's the difference between Reach and Impressions?", opts: ["They are synonyms and mean exactly the same thing across every analytics dashboard and every platform", "Reach is only used for paid campaigns; Impressions is only used for free organic posts without any ads", "Reach = unique people who saw the post. Impressions = total times the post was displayed on any screen", "Reach is always bigger than Impressions because more people see things than the total number of views"], ans: 2, why: "Reach = unique people. Impressions = total views (one person seeing a post 3 times = 1 reach, 3 impressions). Impressions ≥ Reach always. Confusing them inflates perceived audience by 2-5×.", bloom: "remember" },
    { q: "What is CTR (Click-Through Rate) and how is it calculated?", opts: ["The number of likes on a post divided by how many followers the account currently has, written as a percent", "CTR = (clicks ÷ impressions) × 100 — the percentage of times the post was seen that led to a real click", "The total number of new followers gained in a week divided by the number of posts made during that week", "The average number of seconds each viewer spent watching a video before they scrolled past it on their feed"], ans: 1, why: "CTR measures how effective a post or ad is at turning views into clicks. (Clicks ÷ Impressions) × 100. Social ad benchmarks sit around 0.5-2%.", bloom: "remember" },
    { q: "Why do experienced social media marketers call \"likes\" and \"follower count\" vanity metrics?", opts: ["Because they feel impressive to look at but don't necessarily drive real business outcomes like sales or leads", "Because they are always completely fake numbers generated by bots with zero real human activity behind them and most modern teams have moved to exactly this way of doing things", "Because they simply cannot be measured by any modern analytics dashboard available for Instagram or TikTok", "Because the platforms themselves made up these numbers for fun and they do not correspond to anything real"], ans: 0, why: "A post with 1000 likes and 0 sales is a vanity win. Real metrics (CTR, conversions, revenue) tie directly to goals; vanity metrics only tie to ego. Popularity ≠ business results.", bloom: "understand" },
    { q: "Why is engagement rate often more useful than raw engagement count when comparing two brands?", opts: ["Because engagement rate divides engagements by reach, so it adjusts for account size and shows real resonance", "Because engagement count is technically illegal to report in most countries without a special marketing license", "Because engagement rate always produces a much larger and more impressive number for presentation to clients", "Because engagement count cannot actually be calculated by any analytics dashboard currently on the market today"], ans: 0, why: "100 likes on a 1,000-follower account ≠ 100 likes on a 100,000-follower account. Rate normalises for audience size and shows which content actually resonates with the people it reached.", bloom: "understand" },
    { q: "A post has 2,000 reach and 100 engagements. What's the engagement rate?", opts: ["2,000% which would be an impossibly high number that no real post has ever actually reached on any platform", "5% which is above average for most brands and suggests the content genuinely resonates with the audience", "0.05% which would be considered extremely low and a sign that the content is performing very poorly indeed", "20% which would suggest a highly viral post performing way better than almost anything most brands ever achieve"], ans: 1, why: "Engagement rate = (engagements ÷ reach) × 100 = (100 ÷ 2000) × 100 = 5%. Above 3-5% is considered strong; most brands sit at 1-3%.", bloom: "apply" },
    { q: "An ad has 50,000 impressions and 250 clicks. What's the CTR, and is it good?", opts: ["0.5% which is about average for social ads — fine, but there's room to improve creative and targeting", "5% which would be an excellent result and well above normal benchmarks for paid social ad performance", "50% which would be extraordinarily high and almost impossible for any real ad to achieve on any platform", "Cannot be calculated without knowing the total reach and total engagement figures for the exact same period"], ans: 0, why: "250 ÷ 50,000 = 0.5%. Industry benchmarks are 0.5-2%. Below 0.3% usually means creative/targeting needs work. You need the formula AND the benchmark to judge.", bloom: "apply" },
    { q: "A Tashkent café sees its Instagram reach drop 40% in a month. Apply analytics thinking — what's a reasonable first step?", opts: ["Delete the Instagram account entirely and start fresh from zero with a new handle and no followers at all", "Panic and immediately spend the entire remaining yearly marketing budget on paid ads to make up the lost reach", "Check which posts dropped most, compare top vs bottom performers, and test changing format or posting time", "Ignore it completely because reach numbers always fluctuate and there is nothing anyone can do to influence them"], ans: 2, why: "Diagnose before acting. Compare top vs bottom posts to spot the pattern (format, topic, time), then test one change. Deleting or panic-spending skips the analysis that tells you what's actually wrong.", bloom: "apply" },
    { q: "Brand A has 100k followers with 500 engagements per post (0.5%). Brand B has 5k followers with 500 engagements per post (10%). Analyse which has a healthier community.", opts: ["Brand A because a bigger follower count is always a better outcome for every business in every industry", "Brand B because a 10% engagement rate means an audience that actually cares and will refer and convert", "Both are exactly identical because they get the same raw engagement number on every single post they publish", "Neither matters at all because engagement rate is not a real metric used by any serious marketing team today"], ans: 1, why: "A's 0.5% rate suggests most followers are passive or bots. B's smaller-but-active audience is worth more for referrals, word-of-mouth, and conversions. Vanity-metric thinking picks A; real analysis picks B.", bloom: "analyze" },
    { q: "A post gets 100,000 impressions and only 2 clicks. Evaluate what went right, what went wrong, and what to fix.", opts: ["The campaign was perfect because getting 100,000 impressions is always a clear win regardless of clicks", "Delete the post immediately and never try anything like it again because impressions without clicks are useless", "Visual hook worked (massive reach), but CTA failed (0.002% CTR) — keep the creative, rewrite the CTA, test", "Impressions don't matter at all in modern social media and this is actually a meaningless data point overall"], ans: 2, why: "Right: reach was huge, so the visual grabbed eyeballs. Wrong: 0.002% CTR is abysmal, so the CTA failed. Fix: keep the visual, rewrite the CTA (clearer benefit, stronger verb), test variants. Separate what worked from what failed.", bloom: "evaluate" },
    { q: "Design a weekly analytics review template for a social media manager. What 5-7 metrics should be tracked, and what decision does each inform?", opts: ["Just track total followers and nothing else because that single number shows everything that truly matters", "Track 50 different metrics every week so that every possible data point is captured in the weekly review spreadsheet", "Reach, engagement rate, CTR, top/bottom 3 posts, follower growth, conversions — each tied to a concrete action", "Only one metric per week because any more would be too confusing for the social media manager to understand"], ans: 2, why: "Reach = awareness trend. Engagement rate = content relevance. CTR = CTA strength. Top-3 = replicate. Bottom-3 = drop. Follower growth = brand health. Conversions = business impact. Each metric ties to an action, not just reporting.", bloom: "create" },
  ],

  // ─── Topic 5: Social Advertising ───
  5: [
    { q: "What is the key difference between CPC and CPM pricing models?", opts: ["CPC is used only on Facebook, while CPM is used only on Instagram — they cannot be used on any other platform", "CPC and CPM are the same thing, just two different names given to the same pricing model by competing advertisers", "CPC is always cheaper than CPM in every situation and for every type of campaign regardless of the actual goal", "CPC = pay per click; CPM = pay per 1,000 impressions — different goals: clicks vs awareness/views"], ans: 3, why: "CPC (Cost Per Click) = pay only when someone clicks. CPM (Cost Per Mille) = pay per 1,000 views regardless of clicks. Different optimisation goals: CPC for traffic, CPM for awareness.", bloom: "remember" },
    { q: "What is a \"lookalike audience\" in social advertising?", opts: ["A group of people the platform finds based on similarities to an existing customer or follower list you upload", "A group of people who have physically visited your shop in person during the past seven days of normal operation", "A group of celebrities who publicly resemble your brand's official visual style or use similar colours in their posts", "A group of competing businesses in the same industry that are running roughly the same advertising campaigns today"], ans: 0, why: "Lookalike audiences are built by feeding the platform your existing customer/follower data. The platform then finds people who behave similarly — a cheap way to find new qualified audiences.", bloom: "remember" },
    { q: "Why is retargeting (showing ads to people who already visited your site) usually cheaper and more effective than cold targeting?", opts: ["Because retargeting is technically more expensive but the industry has been giving incorrect information for years", "Because Facebook and Instagram give large promotional discounts specifically for retargeting ads by default", "Because warmer audience converts better, so platform auction systems reward engagement with lower prices", "Because retargeting is illegal in most countries and only a few brands can get away with actually doing it"], ans: 2, why: "Warmer audiences (already familiar with the brand) convert better. Platforms reward higher engagement with lower auction prices — double benefit: better conversions + cheaper clicks.", bloom: "understand" },
    { q: "Why does the phrase \"organic is free, so skip paid ads\" oversimplify social advertising?", opts: ["Because organic reach on most platforms is only 2-5% of followers, so paid ads are needed to reach the rest", "Because organic content does not actually exist on modern platforms anymore and everything technically costs money", "Because paid ads are always cheaper than organic posts once you calculate the total cost of creating either of them", "Because platforms have officially announced that organic content is about to be banned from every app worldwide"], ans: 0, why: "Organic reach has collapsed to ~2-5% of followers on most platforms. Paid ads are the mechanism to reach non-followers and break the organic ceiling. Organic builds credibility; paid extends reach.", bloom: "understand" },
    { q: "You want to run an awareness campaign for a new product launch — goal is maximum eyeballs, not immediate sales. Which bidding model fits?", opts: ["CPC because paying per click guarantees that the ad will be shown to the maximum number of possible people", "CPM because paying for impressions matches the awareness goal and gives you the most views for the budget", "Pay-per-conversion only because that is always the most efficient model to use for every kind of campaign ever", "Do not pay for ads at all because organic reach alone is enough for every possible launch regardless of size"], ans: 1, why: "Awareness = impressions goal → CPM. CPC would still work but you'd pay for clicks you don't actually need at this launch stage. Match bidding to goal.", bloom: "apply" },
    { q: "You have two headlines you can't decide between for an ad. Apply A/B testing — how do you run it correctly?", opts: ["Switch headlines every other day for a whole month and then compare the total results added up at the end and most modern teams have moved to exactly this way of doing things", "Run both ads simultaneously to similar audiences, changing only the headline, until results are significant", "Show headline A by itself for a month, then headline B by itself for a month, then compare total numbers", "Ask every team member privately which headline they prefer and go with whichever one gets more team votes"], ans: 1, why: "A/B test rules: change ONE variable, run in parallel (eliminates time-of-day effects), get enough data for significance (~1000+ impressions each). Sequential or multi-variable tests give unreliable results.", bloom: "apply" },
    { q: "A Tashkent clothing brand has $200 to spend on its first ad. Apply best practices — how should they split it?", opts: ["Spend the entire $200 on one single big-budget ad with one creative running for one day to maximise reach", "Boost one existing post by $200 because boosting is always cheaper and better than creating any proper ad", "Split into 2-3 small tests with different creatives or audiences, learn what works, then scale the winner", "Send $200 directly to an influencer without running any ads at all because influencer posts always convert better"], ans: 2, why: "Small tests first — learn which creative + audience works, THEN scale the winner with more budget. Dumping $200 into one untested ad is gambling; splitting into tests is learning.", bloom: "apply" },
    { q: "A brand's ads have high CPC and low CTR. Analyse the likely causes and where to start fixing.", opts: ["The platform itself is broken and the brand should immediately switch to a completely different ad network", "Weak creative → low CTR → algorithmic penalty → high CPC. Start by fixing the creative before anything else", "Just increase the daily budget by a large amount and the problem will automatically solve itself within a week", "Stop advertising entirely and never run another paid ad campaign on any social media platform ever again"], ans: 1, why: "Causes: creative doesn't grab attention → low CTR → platform penalises low engagement with higher prices → CPC rises. Start with the creative (new visuals + headline), retest CTR before touching targeting. Fix cause, not symptom.", bloom: "analyze" },
    { q: "A small business argues: \"Paid ads never work for small shops — only big brands can afford them.\" Evaluate this claim.", opts: ["Correct — paid ads are always a complete waste of money for any small business regardless of its ad goal", "Flawed — even small budgets ($5-20/day) can reach tightly targeted local audiences and drive real foot traffic", "Correct — small shops should only use organic posting because paid ads are too complex for a small team to run", "Paid advertising technically does not exist as a service available to any business with fewer than ten employees"], ans: 1, why: "Targeting + small budgets make paid reach affordable for small shops. A $10/day campaign targeted to 5km around a café can drive real foot traffic. The claim ignores how precise targeting shrinks the minimum effective spend.", bloom: "evaluate" },
    { q: "Design a $500 ad campaign for an online course launch targeting working professionals aged 25-40.", opts: ["Just boost one single post for $500 and hope that the boost reaches the right professional audience automatically", "Spend the entire $500 on one TikTok dance video without any targeting because virality is the only thing that works and most modern teams have moved to exactly this way of doing things", "Lookalike + interest + retargeting audiences; video + carousel + lead form; CPC/conversion bidding; track CPL and ROAS", "Run a banner ad on a news website for $500 because banner ads are always the most effective type of advertising"], ans: 2, why: "Audiences: lookalike of past students, interest targeting (career + industries), retargeting visitors. Formats: video testimonial + carousel + lead form. Split: $150 cold, $200 lookalike, $150 retargeting. Track CPL and ROAS. Design means naming audiences, creatives, bidding, split, AND measurement.", bloom: "create" },
  ],

  // ─── Topic 6: LinkedIn for Students ───
  6: [
    { q: "Why is LinkedIn specifically valuable for students, even before graduation?", opts: ["Because it is technically a legal requirement for every university student worldwide to have an active profile", "Because it is strictly only for people with 10+ years of work experience and nobody younger is allowed on it", "Because it has the best photo filters and the nicest-looking user interface of any current social media platform", "Because recruiters actively search LinkedIn — an early profile means you are findable BEFORE you ever apply"], ans: 3, why: "Recruiters run boolean searches on LinkedIn. A student with projects, coursework, and a professional headshot is discoverable BEFORE they apply — and many roles get filled through searches, not public postings.", bloom: "remember" },
    { q: "What's the purpose of the LinkedIn \"headline\" field directly under your name?", opts: ["A short descriptor that appears next to your name everywhere — searches, comments, requests, feed posts", "A long essay of several paragraphs about your full life story from childhood to your most recent graduation", "A fixed job title chosen from a short platform-controlled list — you cannot type any custom words at all", "A purely decorative text field with no function — recruiters never actually read or consider this particular field"], ans: 0, why: "The headline appears next to your name across the whole platform — searches, comments, connection requests. Specific descriptors trigger profile clicks; generic ones (\"Student\") fail the 2-second scan.", bloom: "remember" },
    { q: "Why does a descriptive headline like \"Marketing Student | Content Creator | Fluent in 3 Languages\" outperform just \"Student\"?", opts: ["Because longer headlines are always automatically promoted by the LinkedIn algorithm regardless of content", "Because it shows up next to your name everywhere — specificity triggers recruiter clicks and memorability", "Because the single word \"Student\" is technically banned from the LinkedIn headline field under the platform rules", "Because LinkedIn actively penalises short headlines and hides any profile that has fewer than 40 total characters"], ans: 1, why: "Your headline appears everywhere your name does. Specific descriptors tell recruiters at a glance what you do; \"Student\" communicates nothing and fails the 2-second scan. Generic = invisible. Specific = clickable.", bloom: "understand" },
    { q: "Why should a student's LinkedIn profile photo be a clear headshot rather than a party selfie or a blurry group photo?", opts: ["Because LinkedIn will automatically delete any profile that uses a non-headshot image as its main profile picture", "Because recruiters form a first impression in 1-2 seconds and an unprofessional photo gets the profile skipped", "Because headshots are technically the only photo type permitted on the platform under its official content rules", "Because every other photo type is illegal under international privacy law whenever it is posted to the internet"], ans: 1, why: "Recruiters scan fast. A clear, friendly headshot signals \"this person takes this seriously\" in the first second; a party selfie signals the opposite. The photo is the single biggest visual signal on the profile.", bloom: "understand" },
    { q: "A student has no formal work experience yet. Apply what you know — what can they put on their LinkedIn profile?", opts: ["Absolutely nothing — they must wait until after graduation and a first real job to create any profile at all", "Fake a job title at a real company to look more impressive to any recruiter who checks the profile online", "Volunteer work, class projects with outcomes, freelance, clubs, certifications, hackathons, a portfolio link", "Leave the entire profile completely blank because writing anything without real work experience is embarrassing"], ans: 2, why: "Demonstrate capability, not tenure. Volunteer work, class projects (with outcome), freelance gigs, club leadership, certifications, hackathons — the profile is a portfolio of evidence, not a résumé of job titles.", bloom: "apply" },
    { q: "You're connecting with an alum you don't know. Apply what you've learned — what makes a good connection request?", opts: ["A personalised short note with a specific reason and no job ask — accept rate rises 3-5× vs default", "No note at all, just the default LinkedIn request — the alum will read your profile and accept anyway", "A very long essay about your full life story and your exact career plans for the next ten years ahead", "A direct demand that they personally get you a job referral at their current employer within two weeks"], ans: 0, why: "Specificity + low ask + respect for their time wins. \"I'm studying marketing; saw you work at X — would value 15 min on how you broke in.\" Generic requests get deleted; demanding job referrals from strangers fails.", bloom: "apply" },
    { q: "An Amity Tashkent student wants their first LinkedIn post. Apply post-choice thinking — which topic is most likely to perform?", opts: ["A personal complaint about a specific lecturer at Amity written in an emotional and angry tone for impact", "A reflection on a concrete class project with what was learned and one lesson others can actually use today", "A copy-pasted generic motivational quote with no personal context or story attached to it in any meaningful way", "A full political opinion piece on an unrelated controversial global topic chosen purely for maximum outrage"], ans: 1, why: "Concrete project + learning + takeaway = professional substance + value for readers. Complaints damage the brand, generic quotes add no value, and controversial unrelated posts kill recruiter interest before they reach the CV.", bloom: "apply" },
    { q: "A student posts 50 LinkedIn articles in one day, then nothing for three months. Analyse why engagement collapses.", opts: ["LinkedIn is glitchy and randomly hides posts at unpredictable times for reasons nobody can ever really understand", "Fifty posts in a day is simply not enough content volume to trigger the LinkedIn algorithm to boost the account", "Algorithm penalises bursts AND silence — consistency beats both extremes over any multi-month horizon here", "Articles are a special content type on LinkedIn that does not count at all toward any follower or engagement growth"], ans: 2, why: "Two causes: (1) algorithm treats 50-in-a-day as spammy and distributes poorly, (2) 3 months of silence breaks the trust/feed presence the algorithm needs. Consistency > bursts. Both extremes are exactly what algorithms suppress.", bloom: "analyze" },
    { q: "A student argues: \"LinkedIn is dead — everyone my age is on TikTok anyway.\" Evaluate this claim.", opts: ["Correct — LinkedIn is completely obsolete now and no student should ever waste time building a profile there", "TikTok fully replaces LinkedIn for every career goal and no student needs both platforms to find a good job", "Correct — skip LinkedIn entirely and just build a huge TikTok following which will replace any job search needed and most modern teams have moved to exactly this way of doing things", "Flawed — LinkedIn reaches recruiters and decision-makers, while TikTok reaches peers; different audiences, both useful"], ans: 3, why: "LinkedIn has 1B+ users and is where recruiters actively search. TikTok excels for peer-to-peer consumer reach. Different audiences for different goals; abandoning LinkedIn forfeits the audience that pays your salary.", bloom: "evaluate" },
    { q: "Design a 4-week LinkedIn ramp-up plan for a 3rd-year Amity Tashkent student.", opts: ["Just create the profile with only a name and nothing else, then never log in again for the rest of the term", "Wait until after graduation before doing anything with LinkedIn because early profiles do not matter at all", "Post 100 times a day every single day for the whole month to flood the algorithm and maximise total reach", "Week 1 profile polish → Week 2 network → Week 3 first post → Week 4 engage on industry posts + post #2"], ans: 3, why: "Week 1: polish (photo, headline, About, experience, skills). Week 2: connect with classmates, professors, alumni. Week 3: first post (class-project reflection). Week 4: second post + substantive comments on 3 industry posts. Ramp-up = setup → network → create → iterate.", bloom: "create" },
  ],

  // ─── Topic 7: Personal Branding ───
  7: [
    { q: "Which definition of personal branding is most accurate?", opts: ["Creating a fancy logo and picking specific brand colours to use on every one of your social media profiles", "Intentionally shaping how others perceive you online through consistent content, profile, and online presence", "Having a million followers on at least one major social media platform of your own personal choice and preference", "Buying the domain yourname.com and registering a matching email address with that same personal domain name"], ans: 1, why: "Personal branding = intentionally shaping how others perceive you through consistent content, profile, and online presence. It's about the signal you send across platforms, not a single asset (logo, domain) or a vanity metric (followers).", bloom: "remember" },
    { q: "Which of these is a \"niche\" in personal branding?", opts: ["Anything and everything you are personally interested in, posted randomly whenever you feel like posting", "Only the single largest and broadest topic possible so that as many people as possible will follow you online", "A focused topic area the brand owns — like \"AI tools for students\" or \"personal finance for first jobs\"", "Your full legal name plus the name of your current university followed by the subject you are studying there"], ans: 2, why: "A niche is a focused topic the brand consistently posts on. Narrow and specific beats broad and vague because niches help audiences remember WHY they followed and the algorithm WHO to recommend you to.", bloom: "remember" },
    { q: "Why does consistency matter more than perfection in personal branding?", opts: ["Algorithms reward frequency; audiences build trust through repetition — imperfect posted beats perfect unposted", "Perfection in social media posts is technically illegal in most countries under various content regulation laws", "Consistency does not actually matter at all and one single perfect post per year is enough to build any brand", "Perfection is always easily achievable for everyone and therefore it should be the main and only goal always"], ans: 0, why: "Algorithms reward regular posting (distribution follows frequency). Audiences form trust through repeated exposure, not through a single flawless post. Imperfect posts published beat perfect posts never published.", bloom: "understand" },
    { q: "Why is a \"niche\" a useful tool when building a personal brand?", opts: ["Because it filters every post decision — \"does this serve my stated audience?\" — and keeps the brand coherent", "Because it technically shrinks your potential audience to the smallest possible number so you can ignore most users", "Because LinkedIn automatically promotes any profile that picks one single niche topic regardless of content quality", "Because niches are legally required to be declared on every professional profile under recent international laws"], ans: 0, why: "A niche is a filter for every content decision. Off-niche posts confuse followers and dilute the brand promise. With a clear niche, the algorithm learns who to recommend you to, and followers know why they follow.", bloom: "understand" },
    { q: "Apply the 70-20-10 rule to a week of LinkedIn posts (3 posts total). What kind of content in each?", opts: ["All three posts should be direct self-promotion and sales pitches for your service or product only", "Roughly 2 value/education posts, 0-1 personal story, and 0-1 promotional — balanced over each month overall", "All three posts should be selfies of yourself taken in different locations and with different filter styles", "All three posts should be memes copied from other accounts without any added commentary or context at all"], ans: 1, why: "Roughly 2 value/education (70%) — insights, tutorials. 0-1 personal (20%) — behind-the-scenes, struggles. At most 0-1 promotional (10%). Mapped to a real 3-post cadence, the ratio prevents the \"just selling\" feed that kills engagement.", bloom: "apply" },
    { q: "Your niche is \"tech + AI for students.\" Apply the niche filter — which of these post ideas fits best?", opts: ["A post about what you ate for breakfast today described in step-by-step detail with every ingredient explained", "Ideas like \"5 AI tools for better study notes,\" \"Lessons from my first ML project,\" \"ChatGPT for exam prep\"", "A post showing only your gym progress over the last six months with workout stats and nutrition details included", "A random post about absolutely anything you find interesting on a given day without any particular theme at all"], ans: 1, why: "Fits the niche: AI study tools, ML project lessons, ChatGPT exam prep — all serve the stated audience (students interested in tech/AI). Off-niche posts dilute the brand and confuse followers about why they followed.", bloom: "apply" },
    { q: "A Tashkent student creator wants to build a personal brand around local food reviews. Apply brand-building basics — what should they do first?", opts: ["Buy 10,000 fake followers immediately so that every real new follower assumes the account is already popular", "Jump across five different platforms in the first week posting everywhere without focus to find an audience", "Pick one platform (e.g. Instagram) and one niche (e.g. Tashkent cafes under 50k som), then post consistently", "Only post one single review every six months and make sure each review is completely and absolutely perfect first"], ans: 2, why: "Start with ONE platform + ONE clear niche + consistency. Bought followers don't engage. Five platforms at once dilutes effort. One post every six months kills any algorithm and trust. Foundation first, expansion later.", bloom: "apply" },
    { q: "A student's professional LinkedIn and personal Twitter show completely different voices. Recruiters find both. Analyse the effect on their brand.", opts: ["No effect at all because recruiters never look at anything outside your main LinkedIn profile page anyway", "Separation is fine (formal vs casual); contradiction is harmful (reckless content undermines the LinkedIn brand)", "Recruiters technically only check LinkedIn and are legally banned from looking at any other social platforms", "Everyone has this situation and it never causes any real problem for any candidate in any job search anywhere and most modern teams have moved to exactly this way of doing things"], ans: 1, why: "Recruiters form an integrated impression across platforms. Different-but-compatible voices (formal LinkedIn, casual Twitter) are fine. Contradictory content (reckless/unprofessional) undermines the professional brand. Separation OK; contradiction harmful.", bloom: "analyze" },
    { q: "A 20-year-old with 50 followers and no \"expertise\" asks whether to bother building a personal brand yet. Evaluate the \"wait\" argument.", opts: ["Wait until after graduation and a real job before posting anything on any platform at all under any circumstances", "Buy 10,000 followers first so the account looks established before posting any content intended for real humans", "Skip personal branding entirely because it is pointless for anyone who is not already famous or well-known today", "Start now — brands compound with time and waiting forfeits the compounding that makes early profiles powerful"], ans: 3, why: "Personal brands compound with time. The 20-year-old who starts at 50 followers and publishes consistently becomes the 24-year-old with a real audience by graduation. The risk of NOT starting outweighs the cost of starting imperfectly.", bloom: "evaluate" },
    { q: "Design a 90-day personal-brand foundation plan for a student with 0 followers targeting a career in product design.", opts: ["Post entirely randomly with no plan or niche and hope that one post eventually goes viral by complete chance", "Do absolutely nothing for 90 days and assume that followers will appear automatically once you finally graduate", "Buy 10,000 followers at the start so the profile looks popular before any real content has ever been posted", "M1 profile + 2 posts/wk → M2 learn-in-public + engage with 5 designers/wk → M3 case study + 1 collaboration"], ans: 3, why: "Month 1: consistent profile (LinkedIn + X + portfolio), 2 posts/wk (design breakdowns, critiques). Month 2: learning-in-public + engage 5 designers/wk. Month 3: long-form case study + 1 peer collab. Order = foundation → content → engagement → output.", bloom: "create" },
  ],
};
